import{_ as o,l as s,o as e,c as i,v as t,p as l,x as r,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"密钥管理与 HSM","description":"","frontmatter":{"title":"密钥管理与 HSM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/key-management-hsm.md","filePath":"cs/key-management-hsm.md","lastUpdated":1789023840000}'),p={name:"cs/key-management-hsm.md"};function c(E,a,S,_,u,A){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="密钥管理与-hsm" tabindex="-1">密钥管理与 HSM <a class="header-anchor" href="#密钥管理与-hsm" aria-label="Permalink to &quot;密钥管理与 HSM&quot;">​</a></h1><div class="epigraph"><p>算法正确只覆盖「运算」；密钥的生成、存放、使用、轮换、销毁才覆盖生命周期。HSM 把私钥关进盒子，让「算而不出」成为策略，而不是再加长 AES。</p><footer>—— 据 NIST SP 800-57；Anderson 对密钥生命周期；对照 PKCS #11 的角色分工</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/hkdf">HKDF</a>会派生多把键。缺口是<strong>这些比特住在哪</strong>。原语课序在 HKDF 结束；本课序从生命周期起。不重写 PRF 定义。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件密钥在进程内存、交换分区、日志、快照里复制。威胁模型若含内存读取，AEAD 帮不上。HSM/TEE 提供：键不导出、使用要授权、审计。缺口是管理平面，不是又一种分组密码。</p><h3 id="hsm-不是魔法" tabindex="-1">HSM 不是魔法 <a class="header-anchor" href="#hsm-不是魔法" aria-label="Permalink to &quot;HSM 不是魔法&quot;">​</a></h3><p>盒子固件、管理卡、备份密钥、提权路径仍是 TCB。Anderson：多数事故是流程，不是因式分解。</p><p><span class="marginnote">SP 800-57 分密钥类型与周期。PKCS #11 是常见 API 形状。后课 seL4 从微内核验证谈 TCB；本课只把 HSM 当密钥的引用监视器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出状态机：生成/注入、激活、轮换、吊销、销毁。对照软件 KMS 与硬件。签名与解密在盒内完成，主机只见明文业务数据或密文。备份用拆分或封装钥。</p>',12)),(e(),l(m,null,{default:r(()=>[h(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%22%5D%20--%3E%20USE%5B%22%E7%9B%92%E5%86%85%E4%BD%BF%E7%94%A8%22%5D%0A%20%20USE%20--%3E%20ROT%5B%22%E8%BD%AE%E6%8D%A2%22%5D%0A%20%20ROT%20--%3E%20DEST%5B%22%E9%94%80%E6%AF%81%22%5D%0A%20%20USE%20--%3E%20POL%5B%22%E6%8E%88%E6%9D%83%E4%B8%8E%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小特权落到键：谁能调用 Sign。前向保密下一课问会话键是否短命——HSM 管长期根，不自动让会话遗忘。二者要一起设计。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某厂商的管理口令默认值清单当利用手册。下一课前向保密：长期根泄漏后历史会话是否仍保密。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HKDF 产出键；本课管键的住处与谁能用。</li><li>HSM 让私钥不可导出成为策略。</li><li>生命周期失败比算法过时更常见。</li><li>下一课：前向保密与短命会话键。</li><li>出处：NIST SP 800-57；Anderson, <em>Security Engineering</em>；PKCS #11。</li></ul>',8))])}const T=o(p,[["render",c]]);export{P as __pageData,T as default};
